/* Posiciones específicas.
   g = grupo compatible con el motor (POR/DEF/MED/DEL). NO se toca: fuerzaEquipo(),
       el conteo de FORMS, nuevoJugador() y las partidas guardadas (j.pos) razonan
       en esas cuatro familias y cambiarlo las rompería todas.
   d = demarcación real. Dentro de DEF, un lateral y un central no son el mismo
       jugador; compartir .g los hacía intercambiables en aptitud, en el XI
       automático, en el reparto de plantillas reales y en los filtros del menú.
       .d es la capa fina que los separa SIN tocar .g — y como vive en esta tabla
       y no en el jugador, ninguna partida guardada necesita migración.
   b = banda del puesto ('D'/'I', vacío si juega por el centro). De aquí sale el
       pie al nacer y el castigo por jugar el carril con el pie cambiado. */
const POSD={
  POR:{g:'POR',d:'POR',b:'', n:'Portero',            p:{div:.21,par:.22,saq:.10,ref:.22,vel:.04,pos:.21}},
  LD :{g:'DEF',d:'LAT',b:'D',n:'Lateral derecho',    p:{rit:.23,tir:.04,pas:.19,reg:.15,def:.26,fis:.13}},
  LI :{g:'DEF',d:'LAT',b:'I',n:'Lateral izquierdo',  p:{rit:.23,tir:.04,pas:.19,reg:.15,def:.26,fis:.13}},
  DFC:{g:'DEF',d:'DFC',b:'', n:'Defensa central',    p:{rit:.09,tir:.02,pas:.11,reg:.05,def:.47,fis:.26}},
  CAD:{g:'DEF',d:'LAT',b:'D',n:'Carrilero derecho',  p:{rit:.26,tir:.06,pas:.20,reg:.17,def:.19,fis:.12}},
  CAI:{g:'DEF',d:'LAT',b:'I',n:'Carrilero izquierdo',p:{rit:.26,tir:.06,pas:.20,reg:.17,def:.19,fis:.12}},
  MCD:{g:'MED',d:'MED',b:'', n:'Mediocentro defensivo',p:{rit:.09,tir:.06,pas:.22,reg:.12,def:.31,fis:.20}},
  MC :{g:'MED',d:'MED',b:'', n:'Mediocentro',        p:{rit:.11,tir:.13,pas:.31,reg:.21,def:.13,fis:.11}},
  MCO:{g:'MED',d:'MED',b:'', n:'Mediapunta',         p:{rit:.14,tir:.21,pas:.29,reg:.27,def:.03,fis:.06}},
  MD :{g:'MED',d:'BAN',b:'D',n:'Volante derecho',    p:{rit:.22,tir:.13,pas:.25,reg:.24,def:.09,fis:.07}},
  MI :{g:'MED',d:'BAN',b:'I',n:'Volante izquierdo',  p:{rit:.22,tir:.13,pas:.25,reg:.24,def:.09,fis:.07}},
  ED :{g:'DEL',d:'BAN',b:'D',n:'Extremo derecho',    p:{rit:.29,tir:.19,pas:.16,reg:.29,def:.02,fis:.05}},
  EI :{g:'DEL',d:'BAN',b:'I',n:'Extremo izquierdo',  p:{rit:.29,tir:.19,pas:.16,reg:.29,def:.02,fis:.05}},
  SD :{g:'DEL',d:'DEL',b:'', n:'Segundo delantero',  p:{rit:.20,tir:.29,pas:.16,reg:.25,def:.02,fis:.08}},
  DC :{g:'DEL',d:'DEL',b:'', n:'Delantero centro',   p:{rit:.19,tir:.39,pas:.09,reg:.14,def:.01,fis:.18}}
};
/* Tabla única de demarcaciones: nombre para los menús. Todo lo que filtre o
   rotule por demarcación sale de aquí, así nadie vuelve a escribir "Laterales"
   a mano en un botón ni se olvida de añadirlo en la segunda pantalla. */
const DEMARCA={
  POR:{n:'Porteros'},  LAT:{n:'Laterales'}, DFC:{n:'Centrales'},
  MED:{n:'Medios'},    BAN:{n:'Bandas'},    DEL:{n:'Delanteros'}
};
/* Un jugador viejo puede no tener posE; entonces sólo queda su j.pos (grupo).
   Este mapa evita que demarca() devuelva undefined y que un filtro nuevo lo
   haga desaparecer del mercado sin explicación. */
const DEM_DEF={POR:'POR',DEF:'DFC',MED:'MED',DEL:'DEL'};
function demarca(j){if(!j)return 'MED';const D=POSD[j.posE];return D?D.d:(DEM_DEF[j.pos]||'MED');}
/* Acepta tanto un puesto ('LD') como un grupo suelto ('DEF') */
function demarcaDe(pe){return (POSD[pe]||{}).d||DEM_DEF[pe]||null;}
/* Estatura por demarcación: el central es el más alto de la línea y el lateral
   el más bajo. Estaba escrito a mano con el mismo ternario en tres sitios y en
   los tres el lateral compartía rango con el mediapunta. */
const ALT_DEM={POR:[184,197],DFC:[181,196],LAT:[168,181],MED:[169,187],BAN:[167,184],DEL:[173,193]};
function alturaPuesto(pe){const r=ALT_DEM[(POSD[pe]||{}).d]||ALT_DEM.MED;return R(r[0],r[1]);}
/* Pie según la banda del puesto. El lateral izquierdo nace zurdo casi siempre y
   el derecho diestro; quien juega por el centro sigue la proporción natural. */
function pieDePuesto(pe){
  const b=(POSD[pe]||{}).b;
  if(!b)return RF()<0.76?'D':'I';
  return RF()<(b==='D'?0.90:0.80)?b:(b==='D'?'I':'D');
}

