function aptitud(j,pe){
  if(!pe||!POSD[pe])return 1;
  const nat=j.posE||sortearPosE(j.pos);
  const D=POSD[pe],N=POSD[nat]||POSD.MC;
  /* El pie deja de ser adorno de ficha: un diestro en el carril izquierdo se
     atraganta con el centro. Va fuera del árbol de puestos porque también
     castiga al lateral NATURAL con el pie cambiado, que es lo que se ve en el
     partido. Sólo en LAT — el extremo a pierna cambiada es un recurso bueno. */
  const lado=(D.d==='LAT'&&D.b&&j.pie&&D.b!==j.pie)?0.94:1;
  if(nat===pe)return 1*lado;
  if((j.posSec||[]).includes(pe))return 0.975*lado;
  if(D.g==='POR'||N.g==='POR')return 0.60;
  if((POS_ADY[nat]||[]).includes(pe))return 0.93*lado;
  /* Mismo grupo, otra demarcación: el central de oficio metido de lateral.
     Caía en el 0.88 genérico y salía casi igual que el titular del puesto;
     ahora paga por no ser lo que es, y el lateral suplente le gana el sitio. */
  if(D.g===N.g)return (D.d===N.d?0.90:0.84)*lado;
  return 0.79*lado;
}

/* El pie y la estatura salen ahora de la demarcación, no de un sorteo plano:
   un lateral izquierdo diestro debe ser la excepción y no la regla, y el
   lateral tiene que ser el más bajo de la línea defensiva. Sin esto, el
   castigo por pie cambiado de aptitud() castigaría a casi todo el mundo. */
j.pie=pieDePuesto(j.posE);
j.altura=alturaPuesto(j.posE);
j.peso=Math.round(j.altura*0.42+R(-4,6));

